import * as THREE from 'three';
export function clothStyle119(id){let h=2166136261;for(const c of String(id)+':pattern'){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return(h>>>0)%4;}
// Built-in vertex colours avoid custom shader compilation on passenger materials.
const variants120=new WeakMap(),sources120=new WeakMap();
export function prepareCloth119(material){material.userData.clothPattern119={value:0};material.vertexColors=true;}
export function applyCloth120(item,id){const style=clothStyle119(id);if(item.clothStyle120===style)return;item.clothStyle120=style;item.body.traverse(o=>{if(!o.isMesh)return;const materials=Array.isArray(o.material)?o.material:[o.material];if(!materials.some(m=>m.userData.clothPattern119))return;const source=sources120.get(o.geometry)||o.geometry;let cache=variants120.get(source);if(!cache){cache=new Map();variants120.set(source,cache);}if(!cache.has(style)){const geometry=source.clone(),p=geometry.attributes.position,colours=new Float32Array(p.count*3);for(let i=0;i<p.count;i++){const y=p.getY(i),fract=v=>v-Math.floor(v),value=style===1?(fract(y*15)>.46?1:.87):style===2?(y>1.11?1:.90):style===3?(fract(y*34)>.17?1:.92):1;colours.set([value,value,value],i*3);}geometry.setAttribute('color',new THREE.BufferAttribute(colours,3));sources120.set(geometry,source);cache.set(style,geometry);}o.geometry=cache.get(style);});}
export function avatarDetail119(item,distance){if(!item.lod119)return;const far=distance>24;if(item.lod119.far===far)return;item.lod119.far=far;for(const o of item.lod119.near)o.visible=!far;for(const o of item.lod119.distant)o.visible=far;}
